import{_ as o,o as t,c as r,a0 as i}from"./chunks/framework.CNXp-E7Q.js";const h=JSON.parse('{"title":"Tutorial: your first bupha run","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/first-run.md","filePath":"tutorials/first-run.md"}'),a={name:"tutorials/first-run.md"};function c(n,e,s,d,u,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="tutorial-your-first-bupha-run" tabindex="-1">Tutorial: your first bupha run <a class="header-anchor" href="#tutorial-your-first-bupha-run" aria-label="Permalink to &quot;Tutorial: your first bupha run&quot;">​</a></h1><p>Goal: push-triggered CI on a repo, end to end, in ~10 minutes.</p><p>Prereqs: <strong>Linux + systemd</strong> (script runner needs bash; macOS/Windows unsupported for now); git; <code>cargo install bupha</code> (until 0.1.0 lands on crates.io: <code>cargo install --git https://github.com/9aia/bupha</code>); docker only if you use the dagger runner. Also a stable public URL for the webhook — named cloudflared tunnel or a direct box; quick tunnels are convenient but flaky.</p><ol><li><code>cd your-repo &amp;&amp; bupha init</code> — scaffolds the dagger module + delegate (the module builds a Rust workspace — needs <code>cargo</code> in the pipeline image; for anything else write <code>ci.sh</code> and use the script runner).</li><li><code>bupha deploy env</code> → set <code>BUPHA_WEBHOOK_SECRET</code> + <code>BUPHA_TOKEN</code> (a repo-scoped PAT) — in <code>~/.config/bupha/env</code>, or store them in your OS keyring with <code>secret-tool</code> (resolution: env → keyring → file).</li><li>Write <code>bupha.toml</code> (see <code>examples/bupha.toml.example</code>): your repo&#39;s <code>[[repo]]</code> entry, <code>runner.kind</code>, <code>tunnel</code>.</li><li><code>bupha doctor</code> — checks this box (binaries, secrets, config) before you commit; fix anything red.</li><li><code>bupha deploy service</code> — systemd unit written + enabled (<code>loginctl enable-linger</code> once for boot persistence).</li><li><code>bupha deploy webhook</code> — registers <code>POST &lt;public_url&gt;/hook</code> on the repo; <code>bupha deploy check</code> verifies unit+secrets+endpoint.</li><li>Push. <code>ci/bupha</code> commit status appears; superseded/cancelled shas get honest error statuses.</li></ol><p>Done. Logs: <code>journalctl --user -u bupha-watch -f</code>.</p>',5)])])}const b=o(a,[["render",c]]);export{h as __pageData,b as default};
